import{_ as n,o as e,c as t,ag as i}from"./chunks/framework.Dx86EdC1.js";const g=JSON.parse('{"title":"Data Penduduk","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/penduduk.md","filePath":"panduan-pengguna/penduduk.md","lastUpdated":1791382762000}'),d={name:"panduan-pengguna/penduduk.md"};function u(r,a,l,s,o,k){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="data-penduduk" tabindex="-1">Data Penduduk <a class="header-anchor" href="#data-penduduk" aria-label="Permalink to &quot;Data Penduduk&quot;">​</a></h1><p>Modul <strong>Buku Induk Penduduk</strong> dikelola di menu <strong>Kependudukan → Penduduk</strong> (<code>/admin/residents</code>).</p><h2 id="menambah-penduduk" tabindex="-1">Menambah Penduduk <a class="header-anchor" href="#menambah-penduduk" aria-label="Permalink to &quot;Menambah Penduduk&quot;">​</a></h2><ol><li>Klik <strong>Tambah Penduduk</strong>.</li><li>Isi data inti: <ul><li><strong>NIK</strong> — tepat 16 digit angka, validasi format, disimpan sebagai string.</li><li><strong>Nama lengkap</strong>, tempat/tanggal lahir, jenis kelamin, gol. darah.</li><li><strong>Agama, status kawin, hubungan keluarga, pendidikan, pekerjaan, kewarganegaraan</strong>.</li><li><strong>KK induk</strong> — pilih kartu keluarga tempat penduduk terdaftar.</li><li>Nama ayah/ibu.</li></ul></li><li><strong>Simpan</strong>.</li></ol><h2 id="pencarian-filter" tabindex="-1">Pencarian &amp; Filter <a class="header-anchor" href="#pencarian-filter" aria-label="Permalink to &quot;Pencarian &amp; Filter&quot;">​</a></h2><ul><li>Pencarian kata kunci mencocokkan <strong>NIK</strong> dan <strong>nama</strong>.</li><li>Filter status penduduk (aktif/mutasi) dan wilayah.</li></ul><div class="tip custom-block"><p class="custom-block-title">Tampilan data terbatas</p><p>Di daftar, NIK ditampilkan dalam bentuk <strong>termasking</strong> (<code>320101********0001</code>) melalui accessor <code>masked_nik</code> untuk meminimalkan paparan data pribadi. NIK penuh hanya tampil pada detail kepada pengguna yang berwenang.</p></div><h2 id="detail-penduduk" tabindex="-1">Detail Penduduk <a class="header-anchor" href="#detail-penduduk" aria-label="Permalink to &quot;Detail Penduduk&quot;">​</a></h2><p>Halaman detail memuat biodata lengkap, relasi keluarga, dan riwayat. Setiap kali detail dibuka, sistem mencatat audit trail <strong><code>ResidentViewed</code></strong> — siapa membuka data siapa dan kapan.</p><h3 id="buat-akun-login-untuk-warga" tabindex="-1">Buat Akun Login untuk Warga <a class="header-anchor" href="#buat-akun-login-untuk-warga" aria-label="Permalink to &quot;Buat Akun Login untuk Warga&quot;">​</a></h3><p>Klik <strong>Buat Akun</strong> (<code>POST /admin/residents/{id}/create-account</code>) untuk memberikan akses portal layanan mandiri kepada penduduk tersebut. Setelah akun aktif, warga bisa login dan <a href="/panduan-pengguna/portal-warga.html">mengajukan surat sendiri</a>.</p><h2 id="mengedit-menghapus" tabindex="-1">Mengedit &amp; Menghapus <a class="header-anchor" href="#mengedit-menghapus" aria-label="Permalink to &quot;Mengedit &amp; Menghapus&quot;">​</a></h2><ul><li><strong>Edit</strong> — perbaiki data; perubahan tercatat di audit log (perubahan oleh user).</li><li><strong>Hapus</strong> — untuk data ganda. Penduduk yang sudah menjadi kepala keluarga sebaiknya tidak dihapus sebelum kepindahan KK.</li></ul><h2 id="data-sensitif-—-aturan-wajib" tabindex="-1">Data Sensitif — Aturan Wajib <a class="header-anchor" href="#data-sensitif-—-aturan-wajib" aria-label="Permalink to &quot;Data Sensitif — Aturan Wajib&quot;">​</a></h2><ul><li>NIK &amp; No KK <strong>tidak pernah</strong> diprint di tempat umum selain dokumen resmi berdisclaimer.</li><li>Jangan menyalin NIK ke spreadsheet yang dibagikan luas.</li><li>Pembatalan/hapus data mengikuti retensi UU PDP — hubungi superadmin untuk kebutuhan penghapusan permanen.</li></ul>',15)])])}const m=n(d,[["render",u]]);export{g as __pageData,m as default};
